func buildCommentWhere[Q sqlite.Filterable](cols commentColumns) commentWhere[Q] {
	return commentWhere[Q]{
		cols:       cols,
		ID:         sqlite.Where[Q, string](cols.ID.Expression),
		CreatedAt:  sqlite.Where[Q, time.Time](cols.CreatedAt.Expression),
		UpdatedAt:  sqlite.Where[Q, time.Time](cols.UpdatedAt.Expression),
		Version:    sqlite.Where[Q, int64](cols.Version.Expression),
		ItemID:     sqlite.Where[Q, string](cols.ItemID.Expression),
		ThreadID:   sqlite.Where[Q, string](cols.ThreadID.Expression),
		Author:     sqlite.Where[Q, string](cols.Author.Expression),
		Source:     sqlite.Where[Q, string](cols.Source.Expression),
		WorkflowID: sqlite.WhereNull[Q, string](cols.WorkflowID.Expression),
		Body:       sqlite.Where[Q, string](cols.Body.Expression),
		EditedAt:   sqlite.WhereNull[Q, time.Time](cols.EditedAt.Expression),
		DeletedAt:  sqlite.WhereNull[Q, time.Time](cols.DeletedAt.Expression),
		DeletedBy:  sqlite.WhereNull[Q, string](cols.DeletedBy.Expression),
		ResolvedAt: sqlite.WhereNull[Q, time.Time](cols.ResolvedAt.Expression),
		ResolvedBy: sqlite.WhereNull[Q, string](cols.ResolvedBy.Expression),
		R:          commentWhereR[Q]{cols: cols},
	}
}

// commentWhereR holds the relationship-based filters of
// commentWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type commentWhereR[Q sqlite.Filterable] struct {
	cols commentColumns
}

// HasCommentMentions filters parents that have a matching CommentMentions using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to CommentMentions).
func (w commentWhereR[Q]) HasCommentMentions(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(CommentMentions.NameExpr()),
		sm.Where(CommentMentions.Columns.CommentID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}

